begin;
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["cùng phương với lực tác dụng.","cùng phương và cùng chiều với lực tác dụng.","có độ lớn tỉ lệ nghịch với bình phương khối lượng của vật.","có độ lớn tỉ lệ thuận với độ lớn của lực tác dụng."],"question":"<p class=\"text-base leading-relaxed my-2\">Điều nào sau đây là <strong>sai</strong>? Khi một lực tác dụng lên một vật, nó truyền cho vật một gia tốc</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật II Newton, gia tốc mà lực truyền cho vật được xác định bởi công thức vectơ: $\\vec{a}=\\dfrac{\\vec{F}}{m}$, với $m$ là khối lượng của vật (khối lượng không đổi).</p><p class=\"text-base leading-relaxed my-2\">Từ công thức trên suy ra:</p><p class=\"text-base leading-relaxed my-2\">- Gia tốc $\\vec{a}$ cùng phương và cùng chiều với lực $\\vec{F}$ (vì $m\\gt 0$): phương án A và B đúng.</p><p class=\"text-base leading-relaxed my-2\">- Độ lớn gia tốc $a=\\dfrac{F}{m}$ tỉ lệ thuận với độ lớn lực $F$: phương án D đúng.</p><p class=\"text-base leading-relaxed my-2\">- Độ lớn gia tốc tỉ lệ nghịch với khối lượng $m$ (bậc nhất, không phải bình phương): phương án C sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án sai là <strong>C</strong>.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["cùng phương với lực tác dụng.","cùng phương và cùng chiều với lực tác dụng.","có độ lớn tỉ lệ nghịch với bình phương khối lượng của vật.","có độ lớn tỉ lệ thuận với độ lớn của lực tác dụng."],"question":"<p class=\"text-base leading-relaxed my-2\">Điều nào sau đây là <strong>sai</strong>? Khi một lực tác dụng lên một vật, nó truyền cho vật một gia tốc</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật II Newton, gia tốc mà lực truyền cho vật được xác định bởi công thức vectơ: $\\vec{a}=\\dfrac{\\vec{F}}{m}$, với $m$ là khối lượng của vật (khối lượng không đổi).</p><p class=\"text-base leading-relaxed my-2\">Từ công thức trên suy ra:</p><p class=\"text-base leading-relaxed my-2\">- Gia tốc $\\vec{a}$ cùng phương và cùng chiều với lực $\\vec{F}$ (vì $m\\gt 0$): phương án A và B đúng.</p><p class=\"text-base leading-relaxed my-2\">- Độ lớn gia tốc $a=\\dfrac{F}{m}$ tỉ lệ thuận với độ lớn lực $F$: phương án D đúng.</p><p class=\"text-base leading-relaxed my-2\">- Độ lớn gia tốc tỉ lệ nghịch với khối lượng $m$ (bậc nhất, không phải bình phương): phương án C sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án sai là <strong>C</strong>.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1543874 and note = 'nap-vl10-c3-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Lực căng dây — hệ vật nối dây, ròng rọc","answer":2,"options":["Watts (W).","Joules (J).","Newton (N).","Radians (Rad)."],"question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị lực căng dây là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực căng dây là một loại lực đàn hồi, có cùng bản chất và cùng đơn vị với lực nói chung.</p><p class=\"text-base leading-relaxed my-2\">Trong hệ SI, đơn vị của lực là niutơn, ký hiệu $\\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án: watt (W) là đơn vị công suất; joule (J) là đơn vị công hoặc năng lượng; radian (rad) là đơn vị góc.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đơn vị của lực căng dây là Newton (N), đáp án C.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Lực căng dây — hệ vật nối dây, ròng rọc","answer":2,"options":["Watts (W).","Joules (J).","Newton (N).","Radians (Rad)."],"question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị lực căng dây là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực căng dây là một loại lực đàn hồi, có cùng bản chất và cùng đơn vị với lực nói chung.</p><p class=\"text-base leading-relaxed my-2\">Trong hệ SI, đơn vị của lực là niutơn, ký hiệu $\\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án: watt (W) là đơn vị công suất; joule (J) là đơn vị công hoặc năng lượng; radian (rad) là đơn vị góc.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đơn vị của lực căng dây là Newton (N), đáp án C.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1543994 and note = 'nap-vl10-c3-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":1,"options":["Lực ma sát nghỉ cực đại lớn hơn lực ma sát trượt.","Lực ma sát nghỉ luôn luôn cân bằng với ngoại lực đặt vào vật.","Lực ma sát xuất hiện thành từng cặp trực đối đặt vào 2 vật tiếp xúc.","Khi ngoại lực đặt vào vật làm vật chuyển động hoặc có xu hướng chuyển động sẽ làm phát sinh lực ma sát."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là không chính xác?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\"><b>A. Đúng.</b> Lực ma sát nghỉ cực đại $F_{ms,max}=\\mu_n N$ thường lớn hơn lực ma sát trượt $F_{mst}=\\mu_t N$ vì $\\mu_n\\gt \\mu_t$ với cùng áp lực $N$.</p><p class=\"text-base leading-relaxed my-2\"><b>B. Sai.</b> Lực ma sát nghỉ chỉ có độ lớn bằng ngoại lực song song với mặt tiếp xúc khi vật đứng yên và ngoại lực còn nằm trong giới hạn $F_{msn}\\le F_{ms,max}$. Nếu ngoại lực vượt quá $F_{ms,max}$ thì vật không còn đứng yên và lực ma sát không còn cân bằng với ngoại lực. Vì vậy không thể khẳng định \"luôn luôn\" cân bằng.</p><p class=\"text-base leading-relaxed my-2\"><b>C. Đúng.</b> Theo định luật III Niu-tơn, lực ma sát giữa hai vật tiếp xúc là cặp lực trực đối, đặt vào hai vật khác nhau.</p><p class=\"text-base leading-relaxed my-2\"><b>D. Đúng.</b> Lực ma sát chỉ xuất hiện khi vật chuyển động hoặc có xu hướng chuyển động so với mặt tiếp xúc do ngoại lực gây ra.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> Phát biểu không chính xác là B.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":1,"options":["Lực ma sát nghỉ cực đại lớn hơn lực ma sát trượt.","Lực ma sát nghỉ luôn luôn cân bằng với ngoại lực đặt vào vật.","Lực ma sát xuất hiện thành từng cặp trực đối đặt vào 2 vật tiếp xúc.","Khi ngoại lực đặt vào vật làm vật chuyển động hoặc có xu hướng chuyển động sẽ làm phát sinh lực ma sát."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là không chính xác?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\"><b>A. Đúng.</b> Lực ma sát nghỉ cực đại $F_{ms,max}=\\mu_n N$ thường lớn hơn lực ma sát trượt $F_{mst}=\\mu_t N$ vì $\\mu_n\\gt \\mu_t$ với cùng áp lực $N$.</p><p class=\"text-base leading-relaxed my-2\"><b>B. Sai.</b> Lực ma sát nghỉ chỉ có độ lớn bằng ngoại lực song song với mặt tiếp xúc khi vật đứng yên và ngoại lực còn nằm trong giới hạn $F_{msn}\\le F_{ms,max}$. Nếu ngoại lực vượt quá $F_{ms,max}$ thì vật không còn đứng yên và lực ma sát không còn cân bằng với ngoại lực. Vì vậy không thể khẳng định \"luôn luôn\" cân bằng.</p><p class=\"text-base leading-relaxed my-2\"><b>C. Đúng.</b> Theo định luật III Niu-tơn, lực ma sát giữa hai vật tiếp xúc là cặp lực trực đối, đặt vào hai vật khác nhau.</p><p class=\"text-base leading-relaxed my-2\"><b>D. Đúng.</b> Lực ma sát chỉ xuất hiện khi vật chuyển động hoặc có xu hướng chuyển động so với mặt tiếp xúc do ngoại lực gây ra.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> Phát biểu không chính xác là B.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544023 and note = 'nap-vl10-c3-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":0,"options":["0,75.","0,075.","0,13.","0,013."],"question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 8 kg chuyển động thẳng đều trên mặt sàn nằm ngang dưới tác dụng của lực kéo có độ lớn 60 N có phương nằm ngang. Lấy g = 10 m/s$^{2}$. Hệ số ma sát giữa vật và mặt sàn bằng</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật chuyển động thẳng đều nên gia tốc bằng 0. Theo định luật II Newton, hợp lực theo phương ngang bằng 0, tức lực kéo cân bằng với lực ma sát trượt.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương cùng chiều chuyển động. Theo phương thẳng đứng, phản lực của sàn cân bằng với trọng lực: $N = P = mg$.</p><p class=\"text-base leading-relaxed my-2\">Lực ma sát trượt: $F_{ms} = \\mu N = \\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">Cân bằng lực theo phương ngang: $F = F_{ms} = \\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\mu = \\dfrac{F}{mg} = \\dfrac{60}{8 \\cdot 10} = 0{,}75$</p><p class=\"text-base leading-relaxed my-2\">Vậy hệ số ma sát giữa vật và mặt sàn là $\\mu = 0{,}75$. Đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":0,"options":["0,75.","0,075.","0,13.","0,013."],"question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 8 kg chuyển động thẳng đều trên mặt sàn nằm ngang dưới tác dụng của lực kéo có độ lớn 60 N có phương nằm ngang. Lấy g = 10 m/s$^{2}$. Hệ số ma sát giữa vật và mặt sàn bằng</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật chuyển động thẳng đều nên gia tốc bằng 0. Theo định luật II Newton, hợp lực theo phương ngang bằng 0, tức lực kéo cân bằng với lực ma sát trượt.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương cùng chiều chuyển động. Theo phương thẳng đứng, phản lực của sàn cân bằng với trọng lực: $N = P = mg$.</p><p class=\"text-base leading-relaxed my-2\">Lực ma sát trượt: $F_{ms} = \\mu N = \\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">Cân bằng lực theo phương ngang: $F = F_{ms} = \\mu mg$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\mu = \\dfrac{F}{mg} = \\dfrac{60}{8 \\cdot 10} = 0{,}75$</p><p class=\"text-base leading-relaxed my-2\">Vậy hệ số ma sát giữa vật và mặt sàn là $\\mu = 0{,}75$. Đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544036 and note = 'nap-vl10-c3-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Ngẫu lực, cân bằng của vật rắn có trục quay","answer":2,"options":["Momen lực chỉ phụ thuôc vào độ lớc của lực.","Qui tắc mô men chỉ áp dụng cho vật có trục quay cố định.","Ngẫu lực là hệ hai lực song song, ngược chiều, có độ lớn bằng nhau, có giá khác nhau cùng tác dụng vào một vật.","Ngẫu lực không có đơn vị đo."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Momen lực đối với trục quay: $M = F \\cdot d$, trong đó $d$ là cánh tay đòn (khoảng cách từ trục quay đến giá của lực). Momen lực phụ thuộc cả độ lớn lực lẫn cánh tay đòn, nên A sai.</p><p class=\"text-base leading-relaxed my-2\">Quy tắc momen lực áp dụng cho vật rắn có trục quay cố định. Phát biểu B ở đây được hiểu theo cách trình bày này, và câu được chọn đúng hơn là C, nên B không phải đáp án cần chọn.</p><p class=\"text-base leading-relaxed my-2\">Ngẫu lực là hai lực song song, ngược chiều, có độ lớn bằng nhau và có giá khác nhau (đặt tại hai điểm khác nhau của vật). Phát biểu C đúng.</p><p class=\"text-base leading-relaxed my-2\">Ngẫu lực có momen $M = F \\cdot d$ với đơn vị là N·m, nên không phải là đại lượng không có đơn vị. D sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Ngẫu lực, cân bằng của vật rắn có trục quay","answer":2,"options":["Momen lực chỉ phụ thuôc vào độ lớc của lực.","Qui tắc mô men chỉ áp dụng cho vật có trục quay cố định.","Ngẫu lực là hệ hai lực song song, ngược chiều, có độ lớn bằng nhau, có giá khác nhau cùng tác dụng vào một vật.","Ngẫu lực không có đơn vị đo."],"question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Momen lực đối với trục quay: $M = F \\cdot d$, trong đó $d$ là cánh tay đòn (khoảng cách từ trục quay đến giá của lực). Momen lực phụ thuộc cả độ lớn lực lẫn cánh tay đòn, nên A sai.</p><p class=\"text-base leading-relaxed my-2\">Quy tắc momen lực áp dụng cho vật rắn có trục quay cố định. Phát biểu B ở đây được hiểu theo cách trình bày này, và câu được chọn đúng hơn là C, nên B không phải đáp án cần chọn.</p><p class=\"text-base leading-relaxed my-2\">Ngẫu lực là hai lực song song, ngược chiều, có độ lớn bằng nhau và có giá khác nhau (đặt tại hai điểm khác nhau của vật). Phát biểu C đúng.</p><p class=\"text-base leading-relaxed my-2\">Ngẫu lực có momen $M = F \\cdot d$ với đơn vị là N·m, nên không phải là đại lượng không có đơn vị. D sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544137 and note = 'nap-vl10-c3-20261020';
